import pandas as pd
import seaborn as sns
import numpy as np
import ast

def task_func(csv_file):
    df = pd.read_csv(csv_file)

    required_columns = {"email", "list"}
    missing = required_columns - set(df.columns)
    if missing:
        raise ValueError(
            f"CSV file must contain columns: {sorted(required_columns)}. Missing: {sorted(missing)}"
        )

    def parse_list_value(value):
        if isinstance(value, (list, tuple, np.ndarray, pd.Series)):
            parsed = value
        else:
            if pd.isna(value):
                raise ValueError("Encountered missing value in 'list' column.")
            parsed = ast.literal_eval(value) if isinstance(value, str) else value

        if isinstance(parsed, np.ndarray):
            parsed = parsed.tolist()
        elif isinstance(parsed, pd.Series):
            parsed = parsed.tolist()
        elif isinstance(parsed, tuple):
            parsed = list(parsed)
        elif not isinstance(parsed, list):
            parsed = [parsed]

        return parsed

    def compute_stats(values):
        if len(values) == 0:
            return 0.0, np.nan, np.nan

        numeric = pd.to_numeric(pd.Series(values, dtype="object"), errors="raise").dropna()
        if numeric.empty:
            return np.nan, np.nan, np.nan

        return float(numeric.sum()), float(numeric.mean()), float(numeric.std(ddof=1))

    parsed_lists = []
    sums = []
    means = []
    stds = []

    for item in df["list"]:
        lst = parse_list_value(item)
        total, mean, std = compute_stats(lst)
        parsed_lists.append(lst)
        sums.append(total)
        means.append(mean)
        stds.append(std)

    result_df = pd.DataFrame(
        {
            "email": df["email"],
            "list": parsed_lists,
            "sum": sums,
            "mean": means,
            "std": stds,
        }
    )

    ax = sns.histplot(data=result_df, x="mean")
    ax.set_title("Histogram of Mean Values")
    ax.set_xlabel("Mean")
    ax.set_ylabel("Count")

    return result_df, ax
